	 * Stores ARG4 as a text cache item under ARG1, with the expiration date and time supplied in ARG2. If the key already exists, its data and metadata are replaced. ARG3 is optional ETag or application metadata and may be an empty string. The key may contain any characters and may be any length, but it must uniquely identify the item. Expiration does not delete: After the expiration time passes, the entry remains on disk and can still be fetched. Use LastHitExpired to detect staleness and a deletion method to remove it.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveTextDt
	 * @param ?string $key
	 * @param CkDateTime $expireDateTime
	 * @param ?string $eTag
	 * @param ?string $itemTextData
	 * @return bool
	 */
	function SaveTextDt($key,$expireDateTime,$eTag,$itemTextData) {
		return CkCache_SaveTextDt($this->_cPtr,$key,$expireDateTime,$eTag,$itemTextData);
	}

	/**
	 * Stores ARG3 as a non-expiring text cache item under ARG1. If the key already exists, its data and metadata are replaced. ARG2 is optional ETag or application metadata and may be an empty string.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveTextNoExpire
	 * @param ?string $key
	 * @param ?string $eTag
	 * @param ?string $itemTextData
	 * @return bool
