	function SaveTextNoExpire($key,$eTag,$itemTextData) {
		return CkCache_SaveTextNoExpire($this->_cPtr,$key,$eTag,$itemTextData);
	}

	/**
	 * Stores ARG4 as a text cache item under ARG1, with ARG2 providing the expiration time as an RFC 822-style Internet date string. If the key already exists, its data and metadata are replaced. ARG3 is optional ETag or application metadata and may be empty. Date alternatives: Use SaveTextDt when the expiration is available as a CkDateTime, or SaveTextNoExpire for an entry without expiration.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveTextStr
	 * @param ?string $key
	 * @param ?string $expireDateTime
	 * @param ?string $eTag
	 * @param ?string $itemTextData
	 * @return bool
	 */
	function SaveTextStr($key,$expireDateTime,$eTag,$itemTextData) {
		return CkCache_SaveTextStr($this->_cPtr,$key,$expireDateTime,$eTag,$itemTextData);
	}

	/**
	 * Stores ARG4 as binary cache data under ARG1, using ARG2 as the expiration date and time. If the key already exists, its data and metadata are replaced. ARG3 is optional ETag or application metadata and may be empty.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveToCacheDt
	 * @param ?string $key
	 * @param CkDateTime $expireDateTime
	 * @param ?string $eTag
	 * @param CkByteData $itemData
	 * @return bool
	 */
	function SaveToCacheDt($key,$expireDateTime,$eTag,$itemData) {
		return CkCache_SaveToCacheDt($this->_cPtr,$key,$expireDateTime,$eTag,$itemData);
	}

	/**
	 * Stores ARG3 as non-expiring binary cache data under ARG1. If the key already exists, its data and metadata are replaced. ARG2 is optional ETag or application metadata and may be empty.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveToCacheNoExpire
	 * @param ?string $key
	 * @param ?string $eTag
	 * @param CkByteData $itemData
	 * @return bool
	 */
	function SaveToCacheNoExpire($key,$eTag,$itemData) {
		return CkCache_SaveToCacheNoExpire($this->_cPtr,$key,$eTag,$itemData);
	}

	/**
	 * Stores ARG4 as binary cache data under ARG1, with ARG2 providing the expiration time as an RFC 822-style Internet date string. If the key already exists, its data and metadata are replaced. ARG3 is optional ETag or application metadata and may be empty. Some language bindings name ARG1 url; it is the cache key and need not be a URL.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#SaveToCacheStr
	 * @param ?string $key
	 * @param ?string $expireDateTime
	 * @param ?string $eTag
	 * @param CkByteData $itemData
	 * @return bool
	 */
	function SaveToCacheStr($key,$expireDateTime,$eTag,$itemData) {
		return CkCache_SaveToCacheStr($this->_cPtr,$key,$expireDateTime,$eTag,$itemData);
	}

	/**
	 * Replaces the expiration date and time of the cache item identified by ARG1 with the CkDateTime value supplied in ARG2. The cached data and ETag are unchanged. Existing item required: This method updates metadata; it does not create a new cache entry when the key is absent.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#UpdateExpirationDt
	 * @param ?string $key
	 * @param CkDateTime $expireDateTime
	 * @return bool
	 */
	function UpdateExpirationDt($key,$expireDateTime) {
		return CkCache_UpdateExpirationDt($this->_cPtr,$key,$expireDateTime);
	}

	/**
	 * Replaces the expiration date and time of the cache item identified by ARG1 with the RFC 822-style Internet date string supplied in ARG2. The cached data and ETag are unchanged. Argument name: Some language bindings name ARG1 url; it is the cache key and does not need to be a URL. Use UpdateExpirationDt for a CkDateTime value.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCacheRef.html#UpdateExpirationStr
	 * @param ?string $key
	 * @param ?string $expireDateTime
